import {E,button,link,field,textarea,select,checkbox,notice,heading,badge,table} from './ui.js';
import {available,addCart,normalizePhone} from './core.js';
import {localizedProduct,textFor,localizeMarkup} from './i18n.js';
import {attach} from './editors.js';

export function checkoutItems(s){return s.buyNow?.items||s.cart;}
export function checkoutView(s){return {...s,cart:checkoutItems(s),coupon:s.buyNow?'':s.coupon};}
export function startBuyNow(s,id,size,color,qty=1){const p=s.products.find(p=>p.id===id);if(!p||p.status!=='Active'||p.archived)throw Error('This product is unavailable.');const items=[];addCart(items,s.products,id,size,qty,color);s.buyNow={items};}
export function relatedProducts(s,p){const list=s.products.filter(x=>x.id!==p.id&&!x.archived&&x.status==='Active'&&x.variants.some(v=>available(x,v.size,v.color)>0));const chosen=p.relatedIds||[];return [...list.filter(x=>chosen.includes(x.id)),...list.filter(x=>!chosen.includes(x.id)&&x.category===p.category),...list.filter(x=>!chosen.includes(x.id)&&x.category!==p.category)].slice(0,4);}
export function eligibleReviewOrders(s,id){if(!s.user?.verified)return [];return s.orders.filter(o=>!o.archived&&o.status==='Delivered'&&(o.customerId?s.user.id&&o.customerId===s.user.id:normalizePhone(o.phone)===normalizePhone(s.user.phone))&&o.items.some(i=>i.id===id));}
export function submitReview(s,id,v,files=[]){const order=eligibleReviewOrders(s,id).find(o=>o.id===v.order);if(!order)throw Error('Only customers with a delivered order can review this product.');s.reviews??=[];if(s.reviews.some(r=>r.productId===id&&r.orderId===order.id))throw Error('A review already exists for this order and product.');const rating=Number(v.rating);if(!Number.isInteger(rating)||rating<1||rating>5)throw Error('Choose a rating from 1 to 5.');if(!v.body?.trim()||v.body.trim().length>2000)throw Error('Write a review of 1–2000 characters.');if(files.length>3)throw Error('Choose up to 3 photos.');const photos=files.map(f=>attach(f,true,true));const review={id:'REV-'+Date.now(),productId:id,orderId:order.id,customerId:s.user.id||null,phone:normalizePhone(s.user.phone),name:s.user.name,rating,body:v.body.trim(),photos,status:'Pending',date:new Date().toISOString(),reply:''};s.reviews.push(review);return review;}
export function reviewSection(s,p){const reviews=(s.reviews||[]).filter(r=>r.productId===p.id&&r.status==='Published');const orders=eligibleReviewOrders(s,p.id).filter(o=>!(s.reviews||[]).some(r=>r.productId===p.id&&r.orderId===o.id));return `<section class="product-section" id="reviews"><h2>Customer reviews</h2>${reviews.length?`<p class="rating-summary">${(reviews.reduce((n,r)=>n+r.rating,0)/reviews.length).toFixed(1)} / 5 · ${reviews.length}</p>`:'<p class="muted mt">No reviews yet.</p>'}${reviews.map(r=>`<article class="review-card"><div class="between"><strong>${E(r.name)}</strong><span aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div>${badge('Verified Purchase')}<p class="mt preserve-lines">${E(r.body)}</p><div class="review-photos">${r.photos.map(f=>`<a href="${E(f.url)}" target="_blank" rel="noopener"><img src="${E(f.url)}" alt="Customer product photo" loading="lazy"></a>`).join('')}</div>${r.reply?`<div class="notice mt"><strong>AELVO</strong><p>${E(r.reply)}</p></div>`:''}</article>`).join('')}${orders.length?`<details class="card mt"><summary>Write a review</summary><form data-form="product-review" data-id="${E(p.id)}" class="mt">${select('Delivered order','order',orders.map(o=>o.id))}${select('Rating','rating',[[5,'★★★★★ · 5'],[4,'★★★★ · 4'],[3,'★★★ · 3'],[2,'★★ · 2'],[1,'★ · 1']])}${textarea('Your review','body','','required maxlength="2000"')}${field('Photos (optional)','reviewPhotos','','file','accept="image/jpeg,image/png,image/webp" multiple')}<p class="form-help">${textFor(s,'Up to 3 photos. Reviews appear after moderation.','সর্বোচ্চ ৩টি ছবি। অনুমোদনের পরে রিভিউ দেখা যাবে।')}</p><div data-error class="error-text"></div><button class="btn">Submit review</button></form></details>`:`<p class="form-help mt">Only customers with a delivered order can review this product.</p>`}</section>`;}
export function productInformation(s,p){return `<section class="product-section"><h2>Description</h2><p class="preserve-lines mt">${E(localizedProduct(s,p,'description'))}</p><h3 class="mt">Product details</h3><dl class="product-specs">${[['material','Material'],['dimensions','Fit / dimensions'],['care','Care instructions']].filter(([key])=>localizedProduct(s,p,key)).map(([key,label])=>`<div><dt>${label}</dt><dd>${E(localizedProduct(s,p,key))}</dd></div>`).join('')||'<p class="muted">No additional details supplied.</p>'}</dl>${button('Size guide','size-guide','','text-link')} · ${link('Delivery & returns','/policy/returns','text-link')}</section>`;}
export function reviewsAdmin(s){return `${heading('Customer reviews','Moderate verified purchase reviews. Original customer text is preserved.')}${table(['Product / customer','Rating','Review','Status','Actions'],(s.reviews||[]).map(r=>[E(s.products.find(p=>p.id===r.productId)?.name)+'<p>'+E(r.name)+'</p>',r.rating+'/5',E(r.body),badge(r.status),button('View / moderate','review-moderate',`data-id="${r.id}"`,'btn small secondary')]))}`;}

const destinations=[['/shop','All products'],['/shop?category=Shoes','Shoes'],['/shop?category=Bags','Bags'],['/shop?category=Wallets','Wallets'],['/about','About AELVO']];
export function validDestination(path){if(!destinations.some(([p])=>p===path))throw Error('Choose a supported storefront destination.');return path;}
export function popupEditor(s){const v=s.saved.popupDraft||s.saved.popup||{};return `${heading('Welcome popup','An optional offer on entry. Up to two buttons.',link('Homepage banner','/admin/banners','btn secondary'))}<form class="card" data-form="welcome-popup">${checkbox('Enable popup','enabled',v.enabled||false)}<div class="field-grid">${field('Heading — English','heading',v.heading||'THE NEW COLLECTION','text','required maxlength="120"')}${field('Heading — বাংলা','headingBn',v.headingBn||'নতুন কালেকশন')}${textarea('Message — English','body',v.body||'Explore the latest AELVO collection.')}${textarea('Message — বাংলা','bodyBn',v.bodyBn||'AELVO-র নতুন কালেকশন দেখুন।')}${field('Image (optional)','popupImage','','file','accept="image/jpeg,image/png,image/webp"')}${checkbox('Remove current image','removeImage',false)}${select('Show frequency','frequency',[['visit','Once per visit'],['daily','Once per day'],['new','First visit only']],v.frequency||'visit')}${field('Delay in seconds','delay',v.delay??0,'number','min="0" max="60" required')}${field('Start (UTC, optional)','start',v.start||'','datetime-local')}${field('End (UTC, optional)','end',v.end||'','datetime-local')}</div>${[1,2].map(i=>`<fieldset class="mt"><legend>Button ${i}</legend><div class="field-grid">${field('Label — English','button'+i,v['button'+i]||(i===1?'Shop Now':'View Offers'))}${field('Label — বাংলা','button'+i+'Bn',v['button'+i+'Bn']||(i===1?'এখনই কিনুন':'কালেকশন দেখুন'))}${select('Destination','destination'+i,destinations,v['destination'+i]||'/shop')}</div><p class="form-help">Leave the label empty to hide this button.</p></fieldset>`).join('')}<div class="error-text" data-error></div><div class="form-actions"><button name="intent" value="Draft" class="btn secondary">Save draft</button><button name="intent" value="Published" class="btn">Publish in preview</button></div><p class="form-help">Checkout, account and payment routes are excluded. Uploads/settings in this frontend reset on refresh.</p></form>`;}
export function savePopup(s,v,file,intent){const delay=Number(v.delay);if(!Number.isFinite(delay)||delay<0||delay>60)throw Error('Delay must be 0–60 seconds.');if(!['visit','daily','new'].includes(v.frequency))throw Error('Choose a valid frequency.');if([v.start,v.end].some(x=>x&&!Number.isFinite(utcTime(x))))throw Error('Choose valid schedule dates.');if(v.start&&v.end&&v.end<=v.start)throw Error('End must be after start.');for(const i of [1,2])validDestination(v['destination'+i]);const previous=s.saved.popupDraft||s.saved.popup;const image=v.removeImage?null:attach(file,false,true)||previous?.image||null;const value={...v,delay,image,revision:String(Date.now()),status:intent||'Draft'};s.saved.popupDraft=value;if(intent==='Published')s.saved.popup=structuredClone(value);return value;}
function utcTime(value){return value?Date.parse(value+'Z'):null;}
export function popupEligible(s,path,now=Date.now(),seen={}){const p=s.saved.popup;if(!p?.enabled||p.status!=='Published'||!['/','/shop','/search'].includes(path)&&!path.startsWith('/product/'))return false;if(p.start&&now<utcTime(p.start)||p.end&&now>=utcTime(p.end))return false;if(s.popupSeen?.[p.revision])return false;if(p.frequency==='new'&&seen.ever)return false;if(p.frequency==='daily'&&seen.day===new Date(now).toISOString().slice(0,10))return false;return true;}
export function popupContent(s){const p=s.saved.popup;return localizeMarkup(`${p.image?`<img class="popup-art" src="${E(p.image.url)}" alt="">`:''}<p class="eyebrow">AELVO FASHION</p><h2>${E(localizedProduct(s,p,'heading'))}</h2><p class="mt preserve-lines">${E(localizedProduct(s,p,'body'))}</p><div class="popup-buttons mt">${[1,2].filter(i=>p['button'+i]).map(i=>link(E(localizedProduct(s,p,'button'+i)),p['destination'+i],i===1?'btn':'btn secondary')).join('')}</div>`,s);}
export function bannerFields(s){const v=s.saved.banner||{};return `<fieldset class="mt"><legend>Homepage media</legend>${select('Media type','mediaType',[['image','Image'],['video','Video']],v.mediaType||'image')}${field('Video (MP4 / WebM, up to 25 MB)','heroVideo','','file','accept="video/mp4,video/webm"')}${field('Poster image (required for video)','heroPoster','','file','accept="image/jpeg,image/png,image/webp"')}${field('Heading — বাংলা','headingBn',v.headingBn||'')}${textarea('Subtitle — বাংলা','subtitleBn',v.subtitleBn||'')}${field('Button — বাংলা','buttonBn',v.buttonBn||'')}<p class="form-help">Muted playback with a pause button. Reduced-motion visitors see the poster first. Publishing replaces the current hero; saving a draft leaves it unchanged.</p></fieldset>`;}
export function saveBanner(s,v,form,intent){const f=n=>form.elements.namedItem(n)?.files?.[0],old=s.saved.banner||{};let video=old.video||null;const file=f('heroVideo');if(file?.size){if(!['video/mp4','video/webm'].includes(file.type)||file.size>25*1024*1024)throw Error('Use MP4 or WebM up to 25 MB.');video={name:file.name,url:URL.createObjectURL(file),type:file.type};}const image=attach(f('image'),false,true)||old.image||null,poster=attach(f('heroPoster'),false,true)||old.poster||null;if(v.mediaType==='video'&&(!video||!poster))throw Error('Upload a video and its poster before saving a video banner.');if(v.start&&!Number.isFinite(Date.parse(v.start)))throw Error('Enter a valid start date.');if(!['Homepage hero','Promotional section'].includes(v.placement))throw Error('Choose a placement.');const value={...v,video,image,poster,status:intent||'Draft'};s.saved.banner=value;if(intent==='Published')s.saved.publishedBanner=structuredClone(value);}
export function homepageHero(s){const v=s.saved.publishedBanner;if(!v||v.placement!=='Homepage hero'||v.start&&Date.now()<utcTime(v.start))return '';const dest={'Category: Shoes':'/shop?category=Shoes','Category: Bags':'/shop?category=Bags','All products':'/shop'}[v.destination]||'/shop';return `<section class="hero managed-hero">${v.mediaType==='video'?`<video id="home-hero-video" muted loop playsinline preload="metadata" poster="${E(v.poster.url)}" data-hero-video><source src="${E(v.video.url)}" type="${E(v.video.type)}"></video>${button('Play video','hero-video','','btn secondary hero-play')}`:`<img src="${E(v.image?.url||'assets/shoe.png')}" alt="${E(v.alt||'')}">`}<div class="hero-copy"><div class="eyebrow">AELVO FASHION</div><h1>${E(localizedProduct(s,v,'heading'))}</h1><p>${E(localizedProduct(s,v,'subtitle'))}</p>${link(E(localizedProduct(s,v,'button')),dest)}</div></section>`;}

export function isOwnerPreview(s){return !s.previewStaff&&(s.previewRole||'Super Admin')==='Super Admin';}
export function ownerAssistantView(s){if(!isOwnerPreview(s))return notice('Only the original Owner account can open this assistant.');return `${heading('Owner AI Assistant','Private workspace · Owner verification required') }<div class="two-col"><form class="card" data-form="owner-ai-verify"><h3>Verify your Owner session</h3>${notice('Backend connection required. This preview does not send email, authenticate an Owner or change live code.')}<p class="mt">A verification code must be delivered to the Owner email already saved on the server.</p>${field('Email verification code','code','','text','inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}"')}${field('AI access password (if configured)','aiPassword','','password','autocomplete="current-password"')}<div data-error class="error-text"></div><div class="form-actions">${button('Send verification code','owner-ai-send','','btn secondary')}<button class="btn">Verify & unlock</button></div></form><div class="card"><h3>Every change needs your approval</h3><ol class="owner-steps"><li>Review the exact proposed change and its affected records/files.</li><li>Confirm that specific proposal before it can run.</li><li>Code changes require backup and successful checks.</li><li>Read the result and audit record; restore a verified backup if needed.</li></ol>${notice('Financial operations are permanently blocked for this assistant: payments, refunds, transfers, balances, payment approval and gateway configuration. It can explain how you can do them yourself.')}<p class="form-help">Session expiry, changed proposal or changed source invalidates approval. A staff role cannot unlock this workspace.</p></div></div><div class="card mt"><h3>Assistant workspace</h3><textarea disabled placeholder="Verify your Owner session after the backend is connected."></textarea><button disabled class="btn mt">Send to Owner AI</button></div>`;}
